// alone (ADR-0021), and on the first line a topic with members goes to
// them alone, so one nobody online may take does not block the rest.
func (q *Queries) LockQueue(ctx context.Context, arg LockQueueParams) ([]Conversation, error) {
	rows, err := q.db.Query(ctx, lockQueue, arg.WorkspaceID, arg.Available, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Conversation
	for rows.Next() {
		var i Conversation
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Number,
			&i.ContactID,
			&i.ChannelID,
			&i.ExternalThreadID,
			&i.Status,
			&i.Priority,
			&i.LineLevel,
			&i.AssigneeID,
			&i.Subject,
			&i.FirstResponseAt,
			&i.LastMessageAt,
			&i.ResolvedAt,
			&i.ClosedAt,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AwaitingFix,
			&i.Rating,
			&i.RatingComment,
			&i.RatingResolvedBy,
			&i.RatedAt,
			&i.TopicID,
			&i.TopicAskedAt,
			&i.LineID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextConversationNumber = `-- name: NextConversationNumber :one
INSERT INTO conversation_counters (workspace_id, last_number)
VALUES ($1, 1)
ON CONFLICT (workspace_id) DO UPDATE SET last_number = conversation_counters.last_number + 1
RETURNING last_number
`

// The row lock serialises numbering per workspace until the transaction ends.
func (q *Queries) NextConversationNumber(ctx context.Context, workspaceID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, nextConversationNumber, workspaceID)
	var last_number int64
	err := row.Scan(&last_number)
	return last_number, err
}

const setAwaitingFix = `-- name: SetAwaitingFix :exec
UPDATE conversations
SET awaiting_fix = $1, version = version + 1, updated_at = now()
WHERE workspace_id = $2 AND id = $3
`

type SetAwaitingFixParams struct {
	AwaitingFix bool
	WorkspaceID uuid.UUID
	ID          uuid.UUID
}

// An open issue is linked to the conversation, or the last one was closed
// (ADR-0012): the inbox shows the mark, clients compare versions.
func (q *Queries) SetAwaitingFix(ctx context.Context, arg SetAwaitingFixParams) error {
	_, err := q.db.Exec(ctx, setAwaitingFix, arg.AwaitingFix, arg.WorkspaceID, arg.ID)
	return err
}

const touchConversation = `-- name: TouchConversation :exec
UPDATE conversations
SET last_message_at = $1,
    first_response_at = CASE WHEN $2::boolean THEN coalesce(first_response_at, $1) ELSE first_response_at END,
    version = version + 1,
    updated_at = now()
WHERE workspace_id = $3 AND id = $4
`

type TouchConversationParams struct {
	At            time.Time
	OperatorReply bool
	WorkspaceID   uuid.UUID
	ID            uuid.UUID
}

// Records a new visible message: inbox order and the first response time.
func (q *Queries) TouchConversation(ctx context.Context, arg TouchConversationParams) error {
	_, err := q.db.Exec(ctx, touchConversation,
		arg.At,
		arg.OperatorReply,
		arg.WorkspaceID,
		arg.ID,
	)
	return err
}

const updateConversationState = `-- name: UpdateConversationState :execrows
UPDATE conversations
SET status = $1,
    assignee_id = $2,
    resolved_at = $3,
    closed_at = $4,
    version = version + 1,
    updated_at = now()
WHERE workspace_id = $5 AND id = $6 AND version = $7
`

type UpdateConversationStateParams struct {
	Status      string
	AssigneeID  *uuid.UUID
	ResolvedAt  *time.Time
	ClosedAt    *time.Time
	WorkspaceID uuid.UUID
	ID          uuid.UUID
	Version     int32
}

// Applies a transition computed in Go. The version guard makes a lost
// update impossible even without the row lock (docs/02 §8).
func (q *Queries) UpdateConversationState(ctx context.Context, arg UpdateConversationStateParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateConversationState,
		arg.Status,
		arg.AssigneeID,
		arg.ResolvedAt,
		arg.ClosedAt,
		arg.WorkspaceID,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
